from save import save
def R(*a): return [{"da":d,"en":e} for d,e in a]
N={}
N["en begravelse"]={"explanation":'"En begravelse" means "a funeral". To say you attend one, use "at deltage i" (to take part in): "Vi deltager i begravelsen" (We are attending the funeral).',"related":R(("at begrave","to bury"),("en grav","a grave"),("en bisættelse","a funeral service"))}
N["en begrundelse"]={"explanation":'"En begrundelse" means "a justification". It is built on "en grund" (a reason). To ask for the reason behind something, say: "Hvad er begrundelsen?" (What is the reason?)',"related":R(("en forklaring","an explanation"),("at begrunde","to justify"),("en undskyldning","an excuse"),("et argument","an argument"))}
N["en begrænsning"]={"explanation":'"En begrænsning" means "a limitation". It is built on "en grænse" (a border or limit). To say there are no limits, use "ingen" (no): "Der er ingen begrænsninger" (There are no limitations).',"related":R(("at begrænse","to limit"),("en restriktion","a restriction"),("en forhindring","an obstacle"),("en barriere","a barrier"))}
N["en begyndelse"]={"explanation":'"En begyndelse" means "a beginning". It is built from "at begynde" (to begin). To say it happens in the first part of something, use "i begyndelsen af" (at the beginning of): "I begyndelsen af filmen er der en storm" (At the beginning of the film there is a storm).',"related":R(("en slutning","an ending"),("en start","a start"),("en afslutning","a conclusion"),("en ende","an end"))}
N["en begynder"]={"explanation":'"En begynder" means "a beginner". It comes from "at begynde" (to begin). To talk about a class for beginners, use "et begynderhold" (a beginners\' class): "Jeg går på et begynderhold" (I am in a beginners\' class).',"related":R(("en nybegynder","a novice"),("en ekspert","an expert"),("en amatør","an amateur"),("en professionel","a professional"))}
N["en behandling"]={"explanation":'"En behandling" means "a treatment". It comes from "at behandle" (to treat). When you talk about how someone is treated, it also means "treatment": "Han fik dårlig behandling" (He got bad treatment).',"related":R(("en undersøgelse","an examination"),("en kur","a course of treatment"),("en terapi","a therapy"))}
N["en bekendt"]={"explanation":'"En bekendt" means "an acquaintance". To say someone is not a close friend, say: "Han er en bekendt, ikke en nær ven" (He is an acquaintance, not a close friend). When a song or a face seems known to you, the adjective "bekendt" means "familiar": "Sangen lyder bekendt" (The song sounds familiar).',"related":R(("at kende","to know"),("kendt","famous"),("ukendt","unknown"))}
N["en bekendtgørelse"]={"explanation":'"En bekendtgørelse" means "an announcement / regulation". It is built from "bekendt" (known) and "at gøre" (to make): it makes something known. In Denmark, a minister issues a "bekendtgørelse" to set out the details of how a law works.',"related":R(("en vejledning","a guideline"),("en meddelelse","a message"),("en kundgørelse","a proclamation"),("et cirkulære","a circular"))}
N["en bekymring"]={"explanation":'"En bekymring" means "a worry". To say you worry, use "at bekymre sig" (literally, to worry yourself): "Jeg bekymrer mig" (I worry). To say you are worried about someone, use the adjective "bekymret" (worried): "Hun er bekymret for sin søn" (She is worried about her son).',"related":R(("en frygt","a fear"),("en uro","unease"),("tryghed","feeling safe"))}
N["en belastning"]={"explanation":'"En belastning" means "a strain". It comes from "at belaste" (to put a load on). To take the strain off someone, use "at aflaste" (to relieve): "Jeg aflaster dig i dag" (I am relieving you today).',"related":R(("et pres","a pressure"),("en overbelastning","an overload"),("en tyngde","a weight"),("en byrde","a burden"))}
N["en belønning"]={"explanation":'"En belønning" means "a reward". To say what you get as a reward, use "som" (as): "Du får en is som belønning" (You get an ice cream as a reward).',"related":R(("at belønne","to reward"),("en straf","a punishment"),("en gave","a gift"),("en præmie","a prize"))}
N["en benzinstation"]={"explanation":'"En benzinstation" means "a gas station". It is built from "benzin" (gasoline) and "en station" (a station). To say you fill the car with fuel, use "at tanke" (to fill up): "Jeg skal tanke på benzinstationen" (I need to fill up at the gas station).',"related":R(("en tankstation","a filling station"),("diesel","diesel"),("en benzinpumpe","a petrol pump"))}
N["en beregning"]={"explanation":'"En beregning" means "a calculation". To say you work something out, use "at lave" (to make): "Jeg laver en beregning af prisen" (I am making a calculation of the price). Do not mix it up with "en regning" (a bill): "Jeg betaler regningen" (I pay the bill).',"related":R(("at beregne","to calculate"),("et regnestykke","a sum"),("et overslag","an estimate"),("en formel","a formula"))}
N["en bersærk"]={"explanation":'"En bersærk" means "a berserker". Danish spells it with "æ", where English has "berserk". To say someone loses control in anger, use "at gå bersærk" (to go berserk): "Han gik bersærk i butikken" (He went berserk in the shop).',"related":R(("en viking","a Viking"),("en kriger","a warrior"),("et raseri","a rage"))}
N["en berøring"]={"explanation":'"En berøring" means "a touch". It comes from "at berøre" (to touch): "Han berørte min arm" (He touched my arm). To describe a gentle one, add "blid" (gentle): "en blid berøring" (a gentle touch).',"related":R(("at røre ved","to touch"),("en følesans","a sense of feeling"),("en kontakt","a contact"),("et strøg","a stroke"))}
N["en besiddelse"]={"explanation":'"En besiddelse" means "a possession". To talk about a person\'s belongings, use the plural: "personlige besiddelser" (personal belongings). When you talk about having something illegal on you, it also means "possession": "besiddelse af stoffer" (possession of drugs).',"related":R(("at eje","to own"),("en ejendom","a property"),("et ejerskab","ownership"),("en ejendel","a belonging"))}
N["en besked"]={"explanation":'"En besked" means "a message". To ask someone to let you know, use "at give besked" (to let someone know): "Giv mig besked i morgen" (Let me know tomorrow). To say you were told something, use "at få besked" (to get word): "Jeg fik besked om mødet" (I was told about the meeting).',"related":R(("en sms","a text message"),("en e-mail","an email"),("et brev","a letter"))}
N["en beskrivelse"]={"explanation":'"En beskrivelse" means "a description". It comes from "at beskrive" (to describe). To tell someone to write a short one, use "kort" (short): "Skriv en kort beskrivelse" (Write a short description).',"related":R(("en forklaring","an explanation"),("en skildring","a portrayal"),("en definition","a definition"))}
N["en beskyldning"]={"explanation":'"En beskyldning" means "an accusation". It comes from "at beskylde" (to accuse). To say someone makes one, use "at komme med" (to come out with): "Han kom med en beskyldning mod mig" (He made an accusation against me).',"related":R(("en anklage","a charge"),("en undskyldning","an excuse / apology"),("at forsvare sig","to defend oneself"))}
N["en beskæresaks"]={"explanation":'"En beskæresaks" means "a pair of pruning shears". It is built from "at beskære" (to prune) and "en saks" (scissors). To say you cut a hedge back, use "at beskære": "Jeg beskærer hækken i april" (I prune the hedge in April).',"related":R(("en hækkeklipper","a hedge trimmer"),("en grensav","a branch saw"),("en havesaks","garden clippers"))}
N["en beslutning"]={"explanation":'"En beslutning" means "a decision". To say you make one, use "at træffe" (to make): "Vi træffer en beslutning" (We make a decision).',"related":R(("at beslutte","to decide"),("et valg","a choice"),("en afgørelse","a ruling"))}
N["en beslutningsproces"]={"explanation":'"En beslutningsproces" means "a decision-making process". It is built from "en beslutning" (a decision) and "en proces" (a process). To say people take part, use "med i" (in on): "Medarbejderne er med i beslutningsprocessen" (The employees take part in the decision-making process).',"related":R(("en afgørelse","a ruling"),("en fremgangsmåde","a procedure"),("en høring","a hearing"),("en beslutningstager","a decision-maker"))}
N["en beslutningstager"]={"explanation":'"En beslutningstager" means "a decision-maker". It is built from "en beslutning" (a decision) and "at tage" (to take). To say who has the last word, add "endelig" (final): "Direktøren er den endelige beslutningstager" (The director is the final decision-maker).',"related":R(("en rådgiver","an advisor"),("en beslutningsproces","a decision-making process"),("en chef","a boss"),("en leder","a leader"))}
N["en bestemmelse"]={"explanation":'"En bestemmelse" means "a provision". It comes from "at bestemme" (to decide). To say what a provision requires, use "ifølge" (according to): "Ifølge bestemmelsen skal du betale i dag" (According to the provision, you must pay today).',"related":R(("en regel","a rule"),("en paragraf","a section"),("en forskrift","a regulation"),("en klausul","a clause"))}
N["en bestilling"]={"explanation":'"En bestilling" means "an order", as in an order placed in a shop. It comes from "at bestille" (to order). To ask whether an order has arrived, say: "Har du modtaget min bestilling?" (Have you received my order?)',"related":R(("en ordre","a business order"),("en levering","a delivery"),("en kvittering","a receipt"),("en reservation","a booking"))}
